    match a
    case Search(q) =>
      if q == "" then m
      else map k | k in m && k.Contains(q) :: m[k]
  }

  function Normalize(m: Model): Model {
    map k | k in m && k != "" :: m[k]
  }

  lemma InitSatisfiesInv()
    ensures Inv(Init())
  {
  }

  lemma StepPreservesInv(m: Model, a: Action)
    ensures Inv(Normalize(Apply(m, a)))
  {
  }

